// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title ContainerOrchestrator
 * @notice Manages encrypted container deployments with async callback resolution
 */
contract ContainerOrchestrator is Ownable {
    using ECDSA for bytes32;

    struct ContainerState {
        bytes32 encryptedConfigHash;
        address deployer;
        uint256 nonce;
        bool active;
        uint64 lastHeartbeat;
    }

    struct CallbackRegistration {
        address target;
        bytes4 selector;
        uint256 containerIdx;
        uint256 gasLimit;
        bool pending;
    }

    mapping(uint256 => ContainerState) public containers;
    mapping(bytes32 => CallbackRegistration) public callbacks;
    mapping(address => uint256) public deployerNonces;

    uint256 public containerCount;
    bytes32[] private callbackQueue;
    mapping(uint256 => bytes32) private containerToCallback;

    event ContainerDeployed(uint256 indexed id, address deployer);
    event CallbackRegistered(bytes32 indexed cbId, uint256 containerIdx);
    event CallbackExecuted(bytes32 indexed cbId, bool success);
    event ContainerTerminated(uint256 indexed id);

    modifier onlyActiveContainer(uint256 _id) {
        require(containers[_id].active, "Container not active");
        require(containers[_id].deployer == msg.sender, "Not deployer");
        _;
    }

    constructor() Ownable() {}

    function deployContainer(
        bytes32 _encryptedConfigHash,
        bytes calldata _signature
    ) external returns (uint256) {
        // Bind the signed message to this contract and chain to prevent
        // cross-contract / cross-chain signature replay.
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                _encryptedConfigHash,
                msg.sender,
                deployerNonces[msg.sender],
                block.chainid,
                address(this)
            )
        );
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        require(ethSignedHash.recover(_signature) == msg.sender, "Invalid signature");

        uint256 id = containerCount++;
        containers[id] = ContainerState({
            encryptedConfigHash: _encryptedConfigHash,
            deployer: msg.sender,
            nonce: deployerNonces[msg.sender]++,
            active: true,
            lastHeartbeat: uint64(block.timestamp)
        });

        emit ContainerDeployed(id, msg.sender);
        return id;
    }

    function registerCallback(
        uint256 _containerIdx,
        address _target,
        bytes4 _selector,
        uint256 _gasLimit
    ) external onlyActiveContainer(_containerIdx) returns (bytes32) {
        require(_gasLimit <= 500000, "Gas limit too high");
        require(_target != address(0), "Invalid target");
        require(_target.code.length > 0, "Target not contract");

        bytes32 cbId = keccak256(
            abi.encodePacked(_containerIdx, _target, _selector, block.timestamp)
        );

        callbacks[cbId] = CallbackRegistration({
            target: _target,
            selector: _selector,
            containerIdx: _containerIdx,
            gasLimit: _gasLimit,
            pending: true
        });

        containerToCallback[_containerIdx] = cbId;
        callbackQueue.push(cbId);

        emit CallbackRegistered(cbId, _containerIdx);
        return cbId;
    }

    function terminateContainer(uint256 _id) external onlyActiveContainer(_id) {
        containers[_id].active = false;
        // Invalidate any pending callback for this container
        bytes32 cbId = containerToCallback[_id];
        if (cbId != bytes32(0) && callbacks[cbId].pending) {
            callbacks[cbId].pending = false;
        }
        delete containerToCallback[_id];
        emit ContainerTerminated(_id);
    }

    function processCallbackQueue(uint256 _batchSize) external onlyOwner {
        uint256 processed = 0;
        uint256 i = 0;

        while (i < callbackQueue.length && processed < _batchSize) {
            bytes32 cbId = callbackQueue[i];
            CallbackRegistration storage cb = callbacks[cbId];

            if (!cb.pending) {
                i++;
                continue;
            }

            // Resolve the container reference with active state check
            ContainerState storage container = containers[cb.containerIdx];

            // Verify container is still active before executing callback
            if (container.active && container.deployer != address(0)) {
                bytes memory callData = abi.encodeWithSelector(
                    cb.selector,
                    cb.containerIdx,
                    container.encryptedConfigHash
                );

                // Checks-effects-interactions: mark as no longer pending
                // BEFORE the external call to prevent reentrant re-execution
                // of the same callback.
                cb.pending = false;
                address target = cb.target;
                uint256 gasLimit = cb.gasLimit;

                (bool success, ) = target.call{gas: gasLimit}(callData);
                emit CallbackExecuted(cbId, success);
                processed++;
            } else {
                // Container no longer active, invalidate callback
                cb.pending = false;
            }
            i++;
        }

        // Compact the queue
        _compactQueue();
    }

    function reassignContainer(uint256 _id, address _newDeployer) external onlyOwner {
        require(_newDeployer != address(0), "Invalid deployer");
        // Invalidate existing callbacks before reassignment
        bytes32 cbId = containerToCallback[_id];
        if (cbId != bytes32(0) && callbacks[cbId].pending) {
            callbacks[cbId].pending = false;
        }
        delete containerToCallback[_id];
        containers[_id].deployer = _newDeployer;
        containers[_id].active = true;
        containers[_id].lastHeartbeat = uint64(block.timestamp);
    }

    function updateEncryptedConfig(
        uint256 _id,
        bytes32 _newConfigHash
    ) external onlyActiveContainer(_id) {
        containers[_id].encryptedConfigHash = _newConfigHash;
        containers[_id].lastHeartbeat = uint64(block.timestamp);
    }

    function getCallbackState(bytes32 _cbId) external view returns (
        address target,
        uint256 containerIdx,
        bool pending,
        bool containerActive
    ) {
        CallbackRegistration storage cb = callbacks[_cbId];
        return (
            cb.target,
            cb.containerIdx,
            cb.pending,
            containers[cb.containerIdx].active
        );
    }

    function _compactQueue() internal {
        uint256 writeIdx = 0;
        for (uint256 readIdx = 0; readIdx < callbackQueue.length; readIdx++) {
            if (callbacks[callbackQueue[readIdx]].pending) {
                if (writeIdx != readIdx) {
                    callbackQueue[writeIdx] = callbackQueue[readIdx];
                }
                writeIdx++;
            }
        }
        while (callbackQueue.length > writeIdx) {
            callbackQueue.pop();
        }
    }
}
